.applied-code { display: flex; align-items: center; justify-content: space-between; gap: 5px; margin-top: 10px; font-size: 13px; }
.applied-code span { display: flex; align-items: center; gap: 5px; }
.applied-code svg { width: 16px; height: 16px; color: var(--olive); }
.grand-total { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-top: 16px; font-size: 17px; font-weight: 700; }
.grand-total small { display: inline-block; margin-left: 3px; color: var(--muted); font-size: 11px; font-weight: 400; }
.grand-total strong { font-size: 23px; line-height: 1.2; letter-spacing: -.035em; white-space: nowrap; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 9px; min-height: 44px; border: 1px solid transparent; border-radius: 6px; padding: 10px 16px; font-size: 14px; font-weight: 650; transition: background .16s ease, border-color .16s ease; }
.primary { background: var(--olive); color: #fff; }
.primary:hover { background: var(--olive-hover); }
.checkout-button { width: 100%; position: relative; margin-top: 17px; min-height: 47px; padding-inline: 35px; }
.checkout-button svg { position: absolute; right: 15px; width: 18px; height: 18px; }
.shipping-meter { margin-top: 17px; }
.shipping-meter > div { display: flex; align-items: center; gap: 8px; font-size: 12px; color: #535e4a; }
.shipping-meter svg { width: 18px; height: 18px; }
.shipping-meter strong { color: var(--olive); }
.shipping-meter progress { display: block; width: 100%; height: 5px; margin-top: 9px; border: 0; overflow: hidden; border-radius: 10px; color: var(--accent); background: #dfe2d4; appearance: none; }
.shipping-meter progress::-webkit-progress-bar { background: #dfe2d4; }
.shipping-meter progress::-webkit-progress-value { background: var(--accent); border-radius: 10px; }
.shipping-meter progress::-moz-progress-bar { background: var(--accent); border-radius: 10px; }

.recommendations { margin-top: 52px; border-top: 1px solid var(--line); padding-top: 33px; }
.section-heading { display: flex; align-items: end; justify-content: space-between; gap: 15px 20px; margin-bottom: 21px; }
.section-heading h2 { font-size: clamp(29px, 3.1vw, 43px); }
.section-heading p { color: var(--muted); font-size: 14px; margin-top: 5px; }
.section-heading .inline-link { margin-bottom: 3px; flex: none; }
.product-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.product-card { min-width: 0; overflow: hidden; border-radius: 9px; border: 1px solid var(--line); background: var(--white); }
.card-photo { aspect-ratio: 1.34; overflow: hidden; background: #e9e2d5; }
